effect.script:
function animate(env,el,p) {
    let globalTime = env.duration * env.time;
    let t = globalTime - (globalTime % (1.0/p.freq));
    var a = p.angle * (Math.PI / 180);
    var dx = Math.sin(a);
    var dy = Math.cos(a);
    let m  = AM.simplexNoise(t*637.729,0,p.seed*394.417);
    dx *= p.mag * m;
    dy *= p.mag * m;
    el.transform.location.x += dx;
    el.transform.location.y += dy;
    return el;
}
